/**
 * Journey map geography — South Asia as five stations and one road.
 *
 * Generated from Natural Earth 1:50m 'Admin 0 – Countries' (public domain,
 * naturalearthdata.com) by a build-time script; do not hand-edit the path
 * data. Projection: plain equirectangular with the x scale multiplied by
 * cos(17.5°) (the map's mid-latitude), fitted so lon 66..92 E and lat 5..31 N
 * fill the viewBox with a 24px margin, centred. Coastlines are simplified
 * (Douglas–Peucker 0.08°, 0.02° around the Palk Strait) and rounded to 0.1px;
 * islands under 0.05 deg² are dropped except Mannar island.
 *
 * Pure data and one pure function. Nothing here reads the DOM or the network.
 */
import type { World } from '../../config';

export const MAP_VIEWBOX = '0 0 720 640';
export const MAP_WIDTH = 720;
export const MAP_HEIGHT = 640;

/* Projection constants — the same fit the generator used, so project() lands
   on the baked coordinates (to within the 0.1px rounding). */
const LON_MIN = 66.0;
const LON_MAX = 92.0;
const LAT_MIN = 5.0;
const LAT_MAX = 31.0;
const MARGIN = 24;
const KX = Math.cos((17.5 * Math.PI) / 180);
const SCALE = Math.min(
  (MAP_WIDTH - 2 * MARGIN) / ((LON_MAX - LON_MIN) * KX),
  (MAP_HEIGHT - 2 * MARGIN) / (LAT_MAX - LAT_MIN),
);
const OFFSET_X = (MAP_WIDTH - (LON_MAX - LON_MIN) * KX * SCALE) / 2;
const OFFSET_Y = (MAP_HEIGHT - (LAT_MAX - LAT_MIN) * SCALE) / 2;

/** Longitude/latitude (degrees) to viewBox coordinates. */
export function project(lon: number, lat: number): { x: number; y: number } {
  return {
    x: OFFSET_X + (lon - LON_MIN) * KX * SCALE,
    y: OFFSET_Y + (LAT_MAX - lat) * SCALE,
  };
}

export interface LandShape {
  name: string;
  /** SVG path data, one or more closed subpaths in viewBox units. */
  d: string;
  /** India and Sri Lanka carry the story; the neighbours are drawn faint. */
  main: boolean;
}

